const input = $input.first().json;

let data = input.output ?? input.text ?? input.response ?? input;
if (typeof data === 'string') data = JSON.parse(data);
if (data.output?.persona) data = data.output;

const enriched = $('Python Enrich').first().json;
const campaignId = enriched.campaign_id ?? enriched.campaign?.id;

if (!campaignId) throw new Error('Thiếu campaign_id.');
if (
  data.hooks?.length !== 10 ||
  data.scripts?.length !== 5 ||
  data.captions?.length !== 5 ||
  data.ctas?.length !== 5
) {
  throw new Error('Cần 10 hooks, 5 scripts, 5 captions và 5 ctas.');
}

for (const [i, hook] of data.hooks.entries()) {
  if (typeof hook !== 'string' || hook.length < 20 || hook.length > 100) {
    throw new Error(`Hook ${i + 1} phải dài 20–100 ký tự.`);
  }
}

const records = data.hooks.map((hook, i) => ({
  persona: data.persona,
  hook,
  script: i < 5 ? data.scripts[i] : null,
  caption: i < 5 ? data.captions[i] : null,
  cta: i < 5 ? data.ctas[i] : null,
}));

return [{ json: { campaign_id: campaignId, records } }];

const input = $input.first().json;

// Tìm phần text Gemini trả về.
// Với response Gemini API, JSON thường nằm trong steps[].content[].text.
const textCandidates = [
  ...(input.steps ?? []).flatMap(step =>
    (step.content ?? [])
      .map(part => part.text)
      .filter(value => typeof value === 'string')
  ),
  input.text,
  input.output?.text,
  typeof input.output === 'string' ? input.output : null,
].filter(value => typeof value === 'string' && value.trim());

let data;

if (textCandidates.length > 0) {
  const rawText = textCandidates[textCandidates.length - 1];

  // Lấy JSON object, bỏ lời dẫn hoặc code fence nếu Gemini có thêm.
  const start = rawText.indexOf('{');
  const end = rawText.lastIndexOf('}');

  if (start === -1 || end <= start) {
    throw new Error(
      'Gemini không trả về JSON object. Hãy kiểm tra output của Gemini - Generate Content Batch.'
    );
  }

  try {
    data = JSON.parse(rawText.slice(start, end + 1));
  } catch (error) {
    throw new Error(
      `Phần JSON Gemini trả về không hợp lệ: ${error.message}`
    );
  }
} else if (input.output && typeof input.output === 'object') {
  data = input.output;
} else {
  data = input;
}

// Tìm campaign_id từ node làm giàu campaign.
const enriched = $('Python - Enrich Campaign').first().json;
const webhook = $('Webhook').first().json;

const campaignId =
  enriched.campaign_id ??
  enriched.campaign?.id ??
  webhook.body?.record?.id ??
  webhook.record?.id;

if (!campaignId) {
  throw new Error(
    'Không tìm thấy campaign_id. Kiểm tra output của Python - Enrich Campaign và Webhook.'
  );
}

// Kiểm tra persona.
const allowedPersonas = [
  'local_guide',
  'family',
  'foodie',
  'budget_traveler',
];

if (!allowedPersonas.includes(data.persona)) {
  throw new Error(
    `Persona không hợp lệ: ${data.persona ?? 'trống'}.`
  );
}

// Kiểm tra số lượng mảng.
const expectedCounts = {
  hooks: 10,
  scripts: 5,
  captions: 5,
  ctas: 5,
};

for (const [field, expected] of Object.entries(expectedCounts)) {
  if (!Array.isArray(data[field]) || data[field].length !== expected) {
    const actual = Array.isArray(data[field])
      ? data[field].length
      : 'không tìm thấy';

    throw new Error(
      `Cần ${expected} ${field}, nhưng nhận được ${actual}. Kiểm tra output Gemini.`
    );
  }
}

// Kiểm tra hook: 20–100 ký tự.
for (const [index, hook] of data.hooks.entries()) {
  if (
    typeof hook !== 'string' ||
    hook.length < 20 ||
    hook.length > 100
  ) {
    throw new Error(
      `Hook ${index + 1} phải dài từ 20 đến 100 ký tự; hiện có ${hook?.length ?? 0}.`
    );
  }
}

// Kiểm tra caption để tránh lỗi validation từ API.
for (const [index, caption] of data.captions.entries()) {
  if (
    typeof caption !== 'string' ||
    caption.length < 40 ||
    caption.length > 2200 ||
    !/#[\p{L}\p{N}_]+/u.test(caption)
  ) {
    throw new Error(
      `Caption ${index + 1} phải dài 40–2200 ký tự và có ít nhất một hashtag hợp lệ.`
    );
  }
}

// Kiểm tra CTA để tránh lỗi validation từ API.
for (const [index, cta] of data.ctas.entries()) {
  if (
    typeof cta !== 'string' ||
    cta.length < 15 ||
    cta.length > 300 ||
    !cta.includes('[LINK_MUA_VE]')
  ) {
    throw new Error(
      `CTA ${index + 1} phải dài 15–300 ký tự và chứa [LINK_MUA_VE].`
    );
  }
}

// Chuyển script dạng object thành text vì cột script trong Supabase là text.
const scriptToText = script => {
  if (typeof script === 'string') {
    return script;
  }

  if (
    !script ||
    typeof script.title !== 'string' ||
    !Array.isArray(script.scenes)
  ) {
    throw new Error(
      'Mỗi script phải có title và scenes dạng mảng.'
    );
  }

  return [
    script.title,
    `Thời lượng: ${script.duration} giây`,
    ...script.scenes,
  ].join('\n');
};

// Tạo 10 records:
// 5 records đầu có đủ script/caption/CTA;
// 5 records còn lại chỉ có hook.
const records = data.hooks.map((hook, index) => ({
  persona: data.persona,
  hook,
  script: index < 5 ? scriptToText(data.scripts[index]) : null,
  caption: index < 5 ? data.captions[index] : null,
  cta: index < 5 ? data.ctas[index] : null,
}));

return [
  {
    json: {
      campaign_id: campaignId,
      records,
    },
  },
];

const items = $input.all();

function getRawText(json) {
  const candidates = [
    json.text,
    json.output,
    json.response?.generations?.[0]?.[0]?.text,
    json.response?.generations?.[0]?.text,
  ];

  return candidates.find((value) => typeof value === 'string');
}

function validate(data, itemIndex) {
  const fail = (message) => {
    throw new Error(`Item ${itemIndex + 1}: ${message}`);
  };

  const requestedPersona = $('Set Persona').first().json.persona;

if (!requestedPersona) {
  throw new Error('Node Set Persona chưa có giá trị persona.');
}

data.persona = requestedPersona;

  const expectedKeys = ['persona', 'hooks', 'scripts', 'captions', 'ctas'];
  const actualKeys = Object.keys(data).sort();

  if (JSON.stringify(actualKeys) !== JSON.stringify([...expectedKeys].sort())) {
    fail('Các key cấp gốc phải đúng là persona, hooks, scripts, captions, ctas.');
  }

  if (data.persona !== 'family') fail('persona phải là family.');

  if (!Array.isArray(data.hooks) || data.hooks.length !== 10) {
    fail('hooks phải có đúng 10 phần tử.');
  }
  data.hooks.forEach((value, i) => {
    if (typeof value !== 'string' || value.length < 20 || value.length > 100) {
      fail(`hook ${i + 1} phải dài 20–100 ký tự.`);
    }
  });

  if (!Array.isArray(data.scripts) || data.scripts.length !== 5) {
    fail('scripts phải có đúng 5 object.');
  }
  data.scripts.forEach((script, i) => {
    const keys = Object.keys(script ?? {}).sort();
    if (JSON.stringify(keys) !== JSON.stringify(['duration', 'scenes', 'title'])) {
      fail(`script ${i + 1} chỉ được có title, duration, scenes.`);
    }
    if (typeof script.title !== 'string' || script.title.length < 10 || script.title.length > 120) {
      fail(`title của script ${i + 1} phải dài 10–120 ký tự.`);
    }
    if (!Number.isInteger(script.duration) || script.duration < 30 || script.duration > 45) {
      fail(`duration của script ${i + 1} phải là số nguyên 30–45.`);
    }
    if (!Array.isArray(script.scenes) || script.scenes.length < 3 || script.scenes.length > 8) {
      fail(`scenes của script ${i + 1} phải có 3–8 phần tử.`);
    }
    script.scenes.forEach((scene, j) => {
      if (typeof scene !== 'string' || scene.length < 10 || scene.length > 500) {
        fail(`scene ${j + 1} của script ${i + 1} phải dài 10–500 ký tự.`);
      }
    });
  });

  if (!Array.isArray(data.captions) || data.captions.length !== 5) {
    fail('captions phải có đúng 5 phần tử.');
  }
  data.captions.forEach((caption, i) => {
    if (
      typeof caption !== 'string' ||
      caption.length < 40 ||
      caption.length > 2200 ||
      !/#[\p{L}\p{N}_]+/u.test(caption)
    ) {
      fail(`caption ${i + 1} phải dài 40–2200 ký tự và có hashtag hợp lệ.`);
    }
  });

  if (!Array.isArray(data.ctas) || data.ctas.length !== 5) {
    fail('ctas phải có đúng 5 phần tử.');
  }
  data.ctas.forEach((cta, i) => {
    if (
      typeof cta !== 'string' ||
      cta.length < 15 ||
      cta.length > 300 ||
      !cta.includes('[LINK_MUA_VE]')
    ) {
      fail(`CTA ${i + 1} phải dài 15–300 ký tự và chứa [LINK_MUA_VE].`);
    }
  });
}

return items.map((item, index) => {
  const raw = getRawText(item.json);

  if (!raw) {
    throw new Error(`Item ${index + 1}: Không tìm thấy trường text từ Basic LLM Chain.`);
  }

  const cleaned = raw
    .replace(/^\s*```(?:json)?\s*/i, '')
    .replace(/\s*```\s*$/, '')
    .trim();

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (error) {
    throw new Error(`Item ${index + 1}: Model trả JSON không hợp lệ: ${error.message}`);
  }

  const data = parsed.output ?? parsed;
  validate(data, index);

  return { json: data };
});
